// Shared cart store: lines kept in localStorage, with a change event so every page can update its count.
export type CartLine = { id: string; quantity: number };

const KEY = "line-shop-cart";
const EVENT = "line-cart-changed";

export function readCart(): CartLine[] {
  try {
    const raw = window.localStorage.getItem(KEY);
    const value = raw ? JSON.parse(raw) : [];
    return Array.isArray(value) ? value : [];
  } catch {
    return [];
  }
}

export function writeCart(lines: CartLine[]): void {
  try {
    window.localStorage.setItem(KEY, JSON.stringify(lines));
  } catch {
    // storage unavailable: the cart lasts for this page only
  }
  window.dispatchEvent(new Event(EVENT));
}

export function addToCart(id: string, quantity: number): void {
  const lines = readCart();
  const hit = lines.find((l) => l.id === id);
  if (hit) hit.quantity += quantity;
  else lines.push({ id, quantity });
  writeCart(lines);
}

export function setQuantity(id: string, quantity: number): void {
  writeCart(readCart().map((l) => (l.id === id ? { ...l, quantity } : l)).filter((l) => l.quantity > 0));
}

export function removeFromCart(id: string): void {
  writeCart(readCart().filter((l) => l.id !== id));
}

export function clearCart(): void {
  writeCart([]);
}

export function subscribeCart(listener: () => void): () => void {
  window.addEventListener(EVENT, listener);
  window.addEventListener("storage", listener);
  return () => {
    window.removeEventListener(EVENT, listener);
    window.removeEventListener("storage", listener);
  };
}

// Mock order service: no network. It numbers the order and keeps the last one for the confirmation page.
export type OrderLine = { id: string; name: string; quantity: number; unitPrice: number };
export type Order = { number: string; lines: OrderLine[]; total: number };

const KEY = "line-shop-last-order";

export async function placeOrder(lines: OrderLine[], total: number): Promise<Order> {
  const order: Order = { number: String(100000 + Math.floor(Math.random() * 900000)), lines, total };
  try {
    window.sessionStorage.setItem(KEY, JSON.stringify(order));
  } catch {
    // storage unavailable: the confirmation page shows no order
  }
  return order;
}

export function readLastOrder(): Order | null {
  try {
    const raw = window.sessionStorage.getItem(KEY);
    return raw ? (JSON.parse(raw) as Order) : null;
  } catch {
    return null;
  }
}

