"use client";
import { useEffect, useState } from "react";
import { readCart, subscribeCart, setQuantity, removeFromCart, clearCart } from "../services/cart";
import type { CartLine } from "../services/cart";
import products from "../fixtures/products.json";

export type CartItem = { id: string; name: string; price: number; quantity: number; lineTotal: number };
type Product = { id: string; name: string; price: number };
const list = products as Product[];

export const SHIPPING_FEE = 5;
export const FREE_SHIPPING_FROM = 100;

/** The cart lines joined with their products, kept up to date as the cart changes. */
export function useCartItems(): CartItem[] {
  const [lines, setLines] = useState<CartLine[]>([]);
  useEffect(() => {
    const update = () => setLines(readCart());
    update();
    return subscribeCart(update);
  }, []);
  const items: CartItem[] = [];
  for (const line of lines) {
    const product = list.find((p) => p.id === line.id);
    if (product) items.push({ id: product.id, name: product.name, price: product.price, quantity: line.quantity, lineTotal: product.price * line.quantity });
  }
  return items;
}

export function cartTotals(items: CartItem[]) {
  const subtotal = items.reduce((sum, i) => sum + i.lineTotal, 0);
  const shipping = items.length === 0 || subtotal >= FREE_SHIPPING_FROM ? 0 : SHIPPING_FEE;
  return { subtotal, shipping, total: subtotal + shipping };
}

export function updateQuantity(id: string, quantity: number): void {
  setQuantity(id, quantity);
}

export function removeItem(id: string): void {
  removeFromCart(id);
}

export function emptyCart(): void {
  clearCart();
}

