import { placeOrder } from "../services/orders";
import type { Order } from "../services/orders";
import { emptyCart } from "./cartItems";
import type { CartItem } from "./cartItems";

export type CheckoutForm = { fullName: string; email: string; address: string; city: string; postalCode: string; terms: boolean };
export type CheckoutErrors = Partial<Record<keyof CheckoutForm, string>>;

/** Checks every field; returns one message per invalid field (none when the form may be sent). */
export function validateCheckout(form: CheckoutForm): CheckoutErrors {
  const errors: CheckoutErrors = {};
  if (!form.fullName.trim()) errors.fullName = "Full name is required";
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email.trim())) errors.email = "Enter a valid email";
  if (!form.address.trim()) errors.address = "Address is required";
  if (!form.city.trim()) errors.city = "City is required";
  if (!/^\d{5}$/.test(form.postalCode.trim())) errors.postalCode = "Postal code must be 5 digits";
  if (!form.terms) errors.terms = "Accept the terms to continue";
  return errors;
}

/** Places the order with the mock service, then empties the cart. */
export async function placeCheckoutOrder(items: CartItem[], total: number): Promise<Order> {
  const order = await placeOrder(items.map((i) => ({ id: i.id, name: i.name, quantity: i.quantity, unitPrice: i.price })), total);
  emptyCart();
  return order;
}

