"use client";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { FormPage } from "../../../library/pages/FormPage";
import { DetailPage } from "../../../library/pages/DetailPage";
import { TextField } from "../../../library/components/TextField";
import { Checkbox } from "../../../library/components/Checkbox";
import { CartLink } from "../../../library/components/CartLink";
import { useCartItems, cartTotals } from "../../../library/usecases/cartItems";
import { useCartCount } from "../../../library/usecases/cartCount";
import { validateCheckout, placeCheckoutOrder } from "../../../library/usecases/checkout";
import type { CheckoutForm, CheckoutErrors } from "../../../library/usecases/checkout";

const EMPTY: CheckoutForm = { fullName: "", email: "", address: "", city: "", postalCode: "", terms: false };

function money(n: number): string {
  return `$${n.toFixed(2)}`;
}

export function CheckoutPage() {
  const router = useRouter();
  const items = useCartItems();
  const count = useCartCount();
  const totals = cartTotals(items);
  const [form, setForm] = useState<CheckoutForm>(EMPTY);
  const [errors, setErrors] = useState<CheckoutErrors>({});
  const field = (key: keyof CheckoutForm) => (value: string) => setForm((f) => ({ ...f, [key]: value }));
  const back = (
    <nav className="flex items-center justify-between">
      <Link href="/cart" className="text-sm underline">Back to cart</Link>
      <CartLink count={count} />
    </nav>
  );
  if (items.length === 0) {
    return (
      <DetailPage title="Checkout" back={back}>
        <p>Your cart is empty</p>
        <Link href="/" className="text-sm underline">Browse the products</Link>
      </DetailPage>
    );
  }
  async function submit() {
    const found = validateCheckout(form);
    setErrors(found);
    if (Object.keys(found).length > 0) return;
    await placeCheckoutOrder(items, totals.total);
    router.push("/order/confirmation");
  }
  return (
    <FormPage
      title="Checkout"
      onSubmit={submit}
      submitLabel="Place order"
      aside={
        <div className="flex flex-col gap-2 rounded-lg border border-slate-200 p-4">
          {back}
          <h2 className="font-semibold">Order summary</h2>
          {items.map((item) => (
            <p key={item.id} className="text-sm">{`${item.name} x ${item.quantity} ${money(item.lineTotal)}`}</p>
          ))}
          <p className="font-semibold">{`Order total ${money(totals.total)}`}</p>
        </div>
      }
    >
      <TextField label="Full name" value={form.fullName} onChange={field("fullName")} error={errors.fullName} />
      <TextField label="Email" value={form.email} onChange={field("email")} error={errors.email} />
      <TextField label="Address" value={form.address} onChange={field("address")} error={errors.address} />
      <TextField label="City" value={form.city} onChange={field("city")} error={errors.city} />
      <TextField label="Postal code" value={form.postalCode} onChange={field("postalCode")} error={errors.postalCode} />
      <Checkbox label="I accept the terms" checked={form.terms} onCheckedChange={(v) => setForm((f) => ({ ...f, terms: v }))} error={errors.terms} />
    </FormPage>
  );
}

